  function num(n) { return Number(n || 0).toLocaleString('en-GB'); }
  function timeAgo(value) {
    const timestamp = new Date(value).getTime();
    if (!Number.isFinite(timestamp)) return 'Recently';
    const minutes = Math.max(0, Math.floor((Date.now() - timestamp) / 60000));
    if (minutes < 1) return 'Just now';
    if (minutes < 60) return `${minutes} min${minutes === 1 ? '' : 's'} ago`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`;
    const days = Math.floor(hours / 24);
    if (days < 30) return `${days} day${days === 1 ? '' : 's'} ago`;
    return new Date(value).toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' });
  }
  async function refreshWeeklyLeaderboard() {
    const hosts=[document.getElementById('home-weekly-leaderboard'),document.getElementById('arcade-weekly-leaderboard')].filter(Boolean);
    if(!hosts.length)return;
    if(!databaseMode){hosts.forEach(host=>host.innerHTML='<div class="empty-state">Live weekly rankings appear here after database sign-in is enabled.</div>');return;}
    hosts.forEach(host=>host.innerHTML='<div class="empty-state">Loading live rankings…</div>');
    try{
      const backend=await window.VABackendReady,rows=await backend.weeklyXpLeaderboard(10);
      const markup=rows.length?rows.map((row,index)=>`<div class="leader-row"><span class="leader-place ${index===0?'first':index===1?'second':''}">${String(row.place||index+1).padStart(2,'0')}</span><span class="avatar ${['avatar-cyan','avatar-purple','avatar-amber'][index%3]}">${esc(String(row.username||'P').trim().charAt(0).toUpperCase())}</span><span class="leader-name"><b><button type="button" class="profile-name-link" data-view-profile-name="${esc(row.username)}">${esc(row.username)}</button></b><small>VOLKS ARCADE · THIS WEEK</small></span><span class="leader-xp">${num(row.weekly_xp)} <small>XP</small></span><span class="leader-badge">✦</span></div>`).join(''):'<div class="empty-state">No public player profiles are available for this ranking.</div>';
      hosts.forEach(host=>host.innerHTML=markup);
    }catch(error){console.warn('Weekly rankings could not load:',error.message);hosts.forEach(host=>host.innerHTML='<div class="empty-state">Weekly rankings are temporarily unavailable.</div>');}
  }
  function renderRecentActivity() {
    const host = document.getElementById('home-activity-list');
    if (!host) return;
    if (recentSignupsState === 'loading') { host.innerHTML = '<div class="empty-state">Loading recent players…</div>'; return; }
    if (recentSignupsState === 'error') { host.innerHTML = '<div class="empty-state">Recent activity is temporarily unavailable.</div>'; return; }
    host.innerHTML = recentSignups.length ? recentSignups.slice(0, 3).map((player, index) => `<div class="activity-item"><span class="activity-icon ${index === 0 ? 'red' : index === 1 ? 'purple' : 'gold'}">✦</span><span><b><button type="button" class="profile-name-link" data-view-profile-name="${esc(player.username)}">${esc(player.username)}</button></b> joined <strong>VOLKS ARCADE</strong><small>${esc(timeAgo(player.created_at))}</small></span></div>`).join('') : '<div class="empty-state">No public player accounts yet. New members will appear here.</div>';
  }
