  const sidebar=document.getElementById('sidebar'),sidebarBackdrop=document.getElementById('sidebar-backdrop'),mobileMenu=document.getElementById('mobile-menu');
  function closeSidebar(){sidebar.classList.remove('mobile-open');sidebarBackdrop.classList.remove('open');mobileMenu.setAttribute('aria-expanded','false');sidebar.setAttribute('aria-hidden',String(matchMedia('(max-width: 620px)').matches));document.body.classList.remove('sidebar-open');}
  function openSidebar(){sidebar.classList.add('mobile-open');sidebarBackdrop.classList.add('open');mobileMenu.setAttribute('aria-expanded','true');sidebar.setAttribute('aria-hidden','false');document.body.classList.add('sidebar-open');}
  mobileMenu.addEventListener('click',()=>sidebar.classList.contains('mobile-open')?closeSidebar():openSidebar());
  document.getElementById('sidebar-close').addEventListener('click',closeSidebar);
  sidebarBackdrop.addEventListener('click',closeSidebar);
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&sidebar.classList.contains('mobile-open')){closeSidebar();mobileMenu.focus();}});
  let swipeStart=null;
  document.addEventListener('pointerdown',event=>{if(!matchMedia('(max-width: 620px)').matches)return;swipeStart={x:event.clientX,y:event.clientY,open:sidebar.classList.contains('mobile-open')};},{passive:true});
  document.addEventListener('pointerup',event=>{if(!swipeStart)return;const dx=event.clientX-swipeStart.x,dy=event.clientY-swipeStart.y,wasOpen=swipeStart.open,startX=swipeStart.x;swipeStart=null;if(Math.abs(dx)<58||Math.abs(dx)<Math.abs(dy)*1.25)return;if(!wasOpen&&startX<26&&dx>0)openSidebar();else if(wasOpen&&dx<0&&startX<280)closeSidebar();},{passive:true});
  sidebar.setAttribute('aria-hidden',String(matchMedia('(max-width: 620px)').matches));
  window.addEventListener('resize',()=>{if(!matchMedia('(max-width: 620px)').matches){sidebar.classList.remove('mobile-open');sidebarBackdrop.classList.remove('open');document.body.classList.remove('sidebar-open');mobileMenu.setAttribute('aria-expanded','false');sidebar.setAttribute('aria-hidden','false');}else if(!sidebar.classList.contains('mobile-open'))sidebar.setAttribute('aria-hidden','true');});
