  function factionCatalog() {
    return [
      { id:'house-volkah', name:"House Vol'Kah", game:'Star Trek Online', requirements:'KDF Alignment', ranks:['Bekk',"La' Commander",'Boq Colonel',"Sa' General","'Aj Admiral",'Vol’Kah Council Members','JoH — Leader of the House'], roles:[] },
      { id:'ueeif', name:'United Empire of Earth Imperial Fleet (UEEIF)', game:'Star Citizen', requirements:'None', ranks:['Colonel','Major','Warrant Officer','Sergeant','Private','Recruit'], roles:[{name:'Founder',rank:'General',permissions:'All Access'},{name:'Officer',rank:'Officer',permissions:'Manage Members, Ranks & Roles'},{name:'Recruitment',rank:'Recruiter',permissions:'Manage Applicants'},{name:'Marketing',rank:'Marketing',permissions:'Manage Branding'}] },
      ...data.factions.map(f => ({ id:f.id || `custom-${slug(f.name)}`, name:f.name, game:f.game, ranks:f.ranks || [], roles:[] })),
      { id:'vampiric-hierarchy', name:'Vampiric Hierarchy', game:'The Elder Scrolls Online', requirements:'EU server', ranks:['Vampire Overlord','Vampire Council','Royal Vampire','Vampire Lord','Vampire General','Vampire','PureBloods'], roles:[] }
    ];
  }
  function slug(value) { return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''); }
  function latestClaim(factionId, status) {
    return data.factionClaims.filter(c => c.factionId === factionId && (!status || c.status === status)).at(-1);
  }
  function factionRankFor(username,factionId){const handle=staffRecord(username)?.gameHandle;return [...(data.factionClaims||[])].reverse().find(claim=>claim.factionId===factionId&&claim.status==='approved'&&(claim.username?.toLowerCase()===String(username).toLowerCase()||claim.characterName?.toLowerCase()===String(username).toLowerCase()||(handle&&claim.characterName?.toLowerCase()===handle.toLowerCase())))?.claimedRank||'Member';}
  function factionRankSummary(username){const handle=staffRecord(username)?.gameHandle;return [...new Map((data.factionClaims||[]).filter(claim=>claim.status==='approved'&&(claim.username?.toLowerCase()===String(username).toLowerCase()||claim.characterName?.toLowerCase()===String(username).toLowerCase()||(handle&&claim.characterName?.toLowerCase()===handle.toLowerCase()))).map(claim=>[claim.factionId,`${claim.factionName}: ${claim.claimedRank}`])).values()].join(' · ')||'No verified faction rank';}
  function chatRooms(){return [{id:'global',name:'Global Arcade Chat',kind:'GLOBAL ROOM',factionId:''},...factionCatalog().map(f=>({id:f.id,name:f.name,kind:f.game.toUpperCase(),factionId:f.id})),...factionCatalog().map(f=>({id:`${f.id}:leaders`,name:`${f.name} · Leaders`,kind:'PRIVATE LEADER ROOM',factionId:f.id,leaderOnly:true}))];}
  function canUseLeaderRoom(room){const role=staffRecord(data.profile.display)?.role,assigned=moderatorAssignmentsFor(data.profile.display).some(item=>item.scope==='platform-chat'||item.scope===`faction:${room.factionId}`),handle=staffRecord(data.profile.display)?.gameHandle;const claim=[...(data.factionClaims||[])].reverse().find(item=>item.factionId===room.factionId&&item.status==='approved'&&(item.username?.toLowerCase()===data.profile.display.toLowerCase()||item.characterName?.toLowerCase()===data.profile.display.toLowerCase()||(handle&&item.characterName?.toLowerCase()===handle.toLowerCase())||role==='Owner'));const rank=String(claim?.claimedRank||'');return Boolean(assigned||claim&&(/leader|overlord|guildmaster|colonel/i.test(rank)||role==='Owner'));}
  function chatRoomAccess(room){if(!data.accountCreated)return 'account';if(room.leaderOnly&&!canUseLeaderRoom(room))return 'leader';const sanction=data.memberOverrides[data.profile.display]||{};if(sanction.status==='banned')return 'banned';if(sanction.status==='suspended'&&sanction.endsAt&&new Date(sanction.endsAt).getTime()>Date.now()&&(sanction.categories||[]).some(category=>['chat','platform'].includes(category)))return 'suspended';return '';}
  function canModerateRoom(roomId){const role=currentStaffRole();if(role==='Owner'||role==='Administrator')return true;const scopes=moderatorAssignmentsFor(data.profile.display).map(item=>item.scope);if(scopes.includes('website')||scopes.includes('platform-chat'))return true;const factionId=String(roomId).replace(/:leaders$/,'');return scopes.includes(`faction:${factionId}`);}
  function isMemberRestricted(username){const record=data.memberOverrides[username]||{};return record.status==='banned'||record.status==='suspended'&&record.endsAt&&new Date(record.endsAt).getTime()>Date.now();}
  function renderPlatformChat(){const roomHost=document.getElementById('platform-room-list'),log=document.getElementById('platform-chat-log');if(!roomHost||!log)return;const rooms=chatRooms(),current=rooms.find(room=>room.id===data.activeChatRoom)||rooms[0],restriction=chatRoomAccess(current);roomHost.innerHTML=rooms.map(room=>{const denied=room.leaderOnly&&!canUseLeaderRoom(room);return `<button type="button" class="platform-room-button ${room.id===current.id?'active':''} ${room.leaderOnly?'leader':''}" data-platform-room="${esc(room.id)}" ${denied?'aria-disabled="true"':''}><span>${room.leaderOnly?'▣':room.id==='global'?'◎':'⚑'}</span><b>${esc(room.name)}</b>${room.leaderOnly?'<small>LOCKED</small>':''}</button>`;}).join('');document.getElementById('platform-room-title').textContent=current.name;document.getElementById('platform-room-kind').textContent=current.kind;const roster=databaseMode?liveMemberDirectory.filter(member=>!current.factionId||(member.factionMemberships||[]).some(entry=>entry.factionId===current.factionId)):[{id:null,name:data.profile.display,rank:current.factionId?factionRankFor(data.profile.display,current.factionId):'Player',level:progress().level},...demoMembers.filter(m=>current.factionId&&m.faction.toLowerCase().includes(current.factionId==='ueeif'?'star citizen':current.factionId==='vampiric-hierarchy'?'vampiric':'house vol')).map(m=>({id:null,name:m.name,rank:m.rank,level:m.level||1}))];document.getElementById('platform-chat-members').innerHTML=roster.map(member=>`<button type="button" class="chat-mention-chip" data-chat-mention="${esc(member.name)}" title="Click to mention ${esc(member.name)}">${esc(member.name)} <small>${esc(member.rank||'Player')} · LVL ${Number(member.level)||1}</small></button>`).join('');const messages=data.platformChats[current.id]||[];log.innerHTML=restriction?`<div class="empty-state">${restriction==='account'?'Create your account to join Platform chat.':restriction==='leader'?'This channel is restricted to verified faction leaders.':'Your chat access is currently restricted by moderation.'}${restriction==='account'?'<button class="button button-primary" data-modal="auth" data-auth-mode="signup">CREATE ACCOUNT</button>':''}</div>`:messages.map(message=>{const own=String(message.author).toLowerCase()===String(data.profile.display).toLowerCase(),staff=canModerateRoom(current.id),authorProfile=liveMemberDirectory.find(member=>String(member.id)===String(message.authorId)),avatar=authorProfile?.avatar?'<img class="chat-message-avatar" src="'+esc(authorProfile.avatar)+'" alt="">':'',controls=`${own?`<button data-edit-chat="${esc(message.id)}">EDIT</button><button data-delete-chat="${esc(message.id)}">DELETE</button>`:''}${staff?`<button data-pin-chat="${esc(message.id)}">${message.pinned?'UNPIN':'PIN'}</button>${!own?`<button data-delete-chat="${esc(message.id)}">REMOVE</button>`:''}`:''}`;return `<article class="platform-message ${message.pinned?'pinned':''}">${avatar}<b>${message.authorId?`<button type="button" class="profile-name-link" data-view-profile="${esc(message.authorId)}">`:''}${esc(message.author)}${message.authorId?'</button>':''} <small>${esc(message.rank||'Player')}</small>${message.pinned?'<span class="pinned-label">PINNED</span>':''}</b><p>${esc(message.text)}</p><time>${new Date(message.createdAt||Date.now()).toLocaleString('en-GB',{dateStyle:'short',timeStyle:'short'})}</time><div class="chat-message-actions">${controls}</div></article>`;}).join('')||'<div class="empty-state">No messages here yet. Start the conversation.</div>';const input=document.querySelector('#platform-chat-form input');if(input)input.disabled=Boolean(restriction);const send=document.querySelector('#platform-chat-form button');if(send)send.disabled=Boolean(restriction);}
  async function refreshLiveChat(roomId, subscribe=true){if(!databaseMode||!data.currentUserId||!roomId)return;try{const backend=await window.VABackendReady,rows=await backend.messages(roomId);data.platformChats[roomId]=rows.reverse().map(row=>({id:row.id,author:row.author_name,authorId:row.author_id,rank:row.rank_name,text:row.body,pinned:Boolean(row.pinned_at),editedAt:row.edited_at,createdAt:row.created_at}));if(data.activeChatRoom===roomId)renderPlatformChat();if(subscribe&&liveChatRoom!==roomId){if(liveChatChannel)await backend.client.removeChannel(liveChatChannel);liveChatRoom=roomId;liveChatChannel=backend.subscribeMessages(roomId,()=>refreshLiveChat(roomId,false));}}catch(error){if(data.activeChatRoom===roomId){const log=document.getElementById('platform-chat-log');if(log)log.innerHTML='<div class="empty-state">This room is not available to your account.</div>';}console.warn('Chat load failed:',error.message);}}
  async function refreshAdminChatData(){if(!databaseMode||!data.currentUserId)return;const backend=await window.VABackendReady;for(const room of chatRooms()){if(!canModerateRoom(room.id))continue;try{const rows=await backend.messages(room.id);data.platformChats[room.id]=rows.reverse().map(row=>({id:row.id,author:row.author_name,authorId:row.author_id,rank:row.rank_name,text:row.body,pinned:Boolean(row.pinned_at),editedAt:row.edited_at,createdAt:row.created_at}));}catch{}}renderAdminChatReview();}
  function renderAdminChatReview(){const host=document.getElementById('admin-chat-review');if(!host)return;const messages=Object.entries(data.platformChats||{}).flatMap(([roomId,items])=>items.map(item=>({...item,roomId}))).filter(item=>canModerateRoom(item.roomId)).slice(-40).reverse();host.innerHTML=messages.length?messages.map(item=>`<article class="admin-chat-message"><span><b>${esc(item.author)}</b><small>${esc(chatRooms().find(room=>room.id===item.roomId)?.name||item.roomId)} · ${esc(item.rank||'Player')}</small><p>${esc(item.text)}</p></span><button type="button" data-remove-chat-message="${esc(item.roomId)}" data-message-id="${esc(item.id||'')}">REMOVE</button></article>`).join(''):'<div class="empty-state">No messages in the rooms assigned to your staff scope.</div>';}
  function renderSanctions(){const host=document.getElementById('admin-sanctions-list');if(!host)return;const active=Object.entries(data.memberOverrides||{}).filter(([,record])=>['banned','suspended'].includes(record.status)).map(([username,record])=>({username,...record,current:true})),activeNames=new Set(active.map(item=>item.username.toLowerCase())),past=(data.moderationHistory||[]).filter(item=>!activeNames.has(String(item.username).toLowerCase())).map(item=>({...item,endsAt:item.currentEnd,startedAt:item.at,current:false,status:item.action})),rows=[...active,...past];host.innerHTML=rows.length?rows.reverse().map(item=>{const expired=item.status==='suspended'&&item.endsAt&&new Date(item.endsAt).getTime()<=Date.now(),state=item.current?(expired?'EXPIRED':item.status.toUpperCase()):String(item.status||'RESTORED').toUpperCase(),remaining=item.status==='banned'?'No expiry':expired?'Expired':item.current?timeRemaining(item.endsAt):new Date(item.at||item.startedAt||Date.now()).toLocaleDateString('en-GB');return `<article class="sanction-row"><b>${esc(item.username)} <span class="sanction-state ${esc(item.status)}">${esc(state)}</span></b><span>${esc(item.reason||'No reason recorded')} · ${item.status==='suspended'?esc((item.categories||[]).join(', ')||'all access')+' · '+remaining:remaining}</span>${item.current?`<button type="button" data-lift-sanction="${esc(item.username)}">RESTORE ACCESS</button>`:''}</article>`;}).join(''):'<div class="empty-state">No current or previous suspensions or bans.</div>';}
  function timeRemaining(timestamp){const ms=new Date(timestamp||0).getTime()-Date.now();if(ms<=0)return 'Expired';const hours=Math.ceil(ms/3600000);if(hours<24)return `${hours} hour${hours===1?'':'s'} left`;const days=Math.ceil(hours/24);return `${days} day${days===1?'':'s'} left`;}
  function factionClaimForm(forSignup=false) {
    return `<div class="faction-application-list">${factionCatalog().map(f => {
      const claim = forSignup ? null : latestClaim(f.id);
      const checked = Boolean(claim && claim.status !== 'declined');
      const rankControl = f.ranks.length
        ? `<select class="field-select" name="rank-${esc(f.id)}">${f.ranks.map((r,i) => { const label = f.id === 'ueeif' ? `Rank ${5-i} (${i < 5 ? '★'.repeat(5-i)+'☆'.repeat(i) : '☆☆☆☆☆'}) — ${r}` : r; return `<option value="${esc(r)}" ${claim?.claimedRank === r ? 'selected' : ''}>${esc(label)}</option>`; }).join('')}</select>`
        : `<input class="field-input" name="rank-${esc(f.id)}" maxlength="48" value="${esc(claim?.claimedRank || '')}" placeholder="Enter your in-game rank" required>`;
      return `<div class="faction-application-card"><label class="faction-choice"><input type="checkbox" data-faction-select="${esc(f.id)}" ${checked ? 'checked' : ''}><span><b>${esc(f.name)}</b><small>${esc(f.game)}</small></span><i>${checked ? 'SELECTED' : 'SELECT'}</i></label><div class="faction-claim-fields" data-faction-fields="${esc(f.id)}" ${checked ? '' : 'hidden'}><div class="faction-claim-grid"><label>IN-GAME CHARACTER<input class="field-input" name="character-${esc(f.id)}" maxlength="32" value="${esc(claim?.characterName || (forSignup?'':data.profile.display))}" placeholder="Character or player name" required></label><label>CLAIMED FACTION RANK${rankControl}</label></div><small>Self-reported only. A moderator will check this character and rank in game before approval.</small></div></div>`;
    }).join('')}</div>`;
  }
  function wireFactionClaimChoices(container) {
    container.querySelectorAll('[data-faction-select]').forEach(check => {
      const fields = container.querySelector(`[data-faction-fields="${CSS.escape(check.dataset.factionSelect)}"]`);
      const sync = () => {
        fields.hidden = !check.checked;
        fields.querySelectorAll('input,select,textarea').forEach(control => { control.disabled = !check.checked; });
        check.closest('.faction-choice').querySelector('i').textContent = check.checked ? 'SELECTED' : 'SELECT';
      };
      check.addEventListener('change', sync);
      sync();
    });
  }

