  async function openDrawer(kind) {
    if(kind!=='notifications'){route('platform');return;}
    const drawer=document.getElementById('utility-drawer'),title=document.getElementById('drawer-title'),eyebrow=document.getElementById('drawer-eyebrow'),content=document.getElementById('drawer-content');
    title.textContent='Notifications';eyebrow.textContent='ACCOUNT + STAFF ACTIVITY';
    if(databaseMode&&data.currentUserId)await refreshAccountNotifications();
    const username=String(data.profile?.display||'').trim().toLowerCase(),pins=(data.notifications||[]).filter(note=>note.type==='pin'&&String(note.username||'').trim().toLowerCase()===username),attention=data.adminAttention||[];
    let markedRead=false;pins.forEach(note=>{if(!note.read){note.read=true;markedRead=true;}});if(markedRead)persist();
    if(databaseMode&&data.currentUserId&&(data.databaseNotifications||[]).some(note=>!note.read_at)){
      try{const backend=await window.VABackendReady;await backend.markNotificationsRead(data.currentUserId);data.databaseNotifications=(data.databaseNotifications||[]).map(note=>({...note,read_at:note.read_at||new Date().toISOString()}));}catch(error){console.warn('Notifications could not be marked read:',error.message);}
    }
    updateNotificationBadge();
    const serverRows=(data.databaseNotifications||[]).slice(0,25);
    const savedHtml=serverRows.length?`<div class="drawer-section-label">ACCOUNT NOTIFICATIONS</div>${serverRows.map(note=>`<button type="button" class="notification-item" data-notification-route="${['platform','community','home'].includes(String(note.target_url||'').replace('#',''))?String(note.target_url).replace('#',''):'home'}"><i class="notice-dot ${note.read_at?'read':''}"></i><span><b>${esc(note.title)}</b><small>${esc(note.body)}</small><time>${new Date(note.created_at).toLocaleString('en-GB',{dateStyle:'short',timeStyle:'short'})}</time></span></button>`).join('')}`:'';
    const staffHtml=attention.length?`<div class="drawer-section-label">NEEDS STAFF ATTENTION</div>${attention.map(item=>`<button type="button" class="notification-item admin-attention-item" data-admin-review-target="${esc(item.target)}" ${item.tab?`data-admin-review-tab="${esc(item.tab)}"`:''}><i class="notice-dot attention-dot"></i><span><b>${esc(item.label)}</b><small>${Number(item.count)} awaiting review · Open queue ↗</small></span></button>`).join('')}`:'';
    const pinHtml=`<div class="drawer-section-label">PINNED MESSAGE ALERTS</div>${pins.length?pins.map(note=>`<div class="notification-item"><i class="notice-dot"></i><div><b>${esc(note.by)} pinned your message.</b><small>In ${esc(note.room)}</small><time>${new Date(note.at).toLocaleString('en-GB',{dateStyle:'short',timeStyle:'short'})}</time></div></div>`).join(''):'<div class="empty-state">No pinned-message notifications.</div>'}`;
    content.innerHTML=savedHtml+staffHtml+pinHtml;
    content.querySelectorAll('[data-notification-route]').forEach(button=>button.addEventListener('click',()=>{closeDrawer();route(button.dataset.notificationRoute);}));
    document.getElementById('drawer-backdrop').classList.add('open');drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');
  }
